<template><view class="screen detail-page"><TVNavigation v-if="TV_BUILD" :active="tvActive"/><view class="row between"><button id="tv-detail-back" :data-sn-down="TV_BUILD&&detail?'#tv-favorite':undefined" class="quiet" @click="back">‹ 返回</button><button :data-sn-down="TV_BUILD&&detail?'#tv-favorite':undefined" class="quiet" :disabled="busy" @click="refresh">刷新</button></view><view v-if="busy&&!detail" class="empty">正在加载影视资料…</view><view v-if="error" class="notice error">{{error}}</view><template v-if="detail"><view class="hero row"><PosterImage class="poster" :src="detail.poster" :title="detail.title" :cache-key="detail.sourceId+':'+detail.id" eager/><view class="hero-copy"><text class="eyebrow">{{detail.categories.map(x=>x.name).join(' · ')}}</text><text class="title">{{detail.title}}</text><text class="hint">{{detail.year}} {{detail.remarks}}</text><button id="tv-favorite" :data-sn-up="TV_BUILD?'#tv-detail-back':undefined" :data-sn-down="TV_BUILD?(resume?'#tv-resume':detail.routes.length>1?'#tv-route-first':'#tv-episodes-first'):undefined" class="primary favorite" @click="toggleFavorite">{{favorite?'✓ 已加入追剧':'＋ 加入追剧'}}</button></view></view>
<view v-if="resume" class="card resume"><text>上次看到 {{resume.episodeLabel}}</text><text class="hint">{{formatTime(resume.position)}}</text><button id="tv-resume" :data-sn-up="TV_BUILD?'#tv-favorite':undefined" :data-sn-down="TV_BUILD?(detail.routes.length>1?'#tv-route-first':'#tv-episodes-first'):undefined" class="primary full" @click="continueWatching">继续观看</button></view><view v-if="recoveryContext" class="notice">已找到同剧资源，请选择要继续的集数<text class="hint">上次看到 {{recoveryContext.episodeLabel}} · {{formatTime(recoveryContext.position)}}</text></view>
<view class="row between section-heading"><text class="section-title">选集播放</text><button class="quiet" :disabled="recovering||sourceState.mode==='fixed'" @click="reportMissing">{{recovering?'正在查找…':'反馈缺集'}}</button></view><view v-if="detail.routes.length>1" class="route-row"><button v-for="(route,index) in detail.routes" :key="route.id" :id="index===0?'tv-route-first':undefined" :data-sn-up="TV_BUILD?(resume?'#tv-resume':'#tv-favorite'):undefined" :data-sn-down="TV_BUILD?'#tv-episodes-first':undefined" :class="['route',{selected:route.id===routeId}]" @click="routeId=route.id">{{/m3u8/i.test(route.name)?'高清线路':route.name}}</button></view><view v-if="!episodes.length" class="notice">这个资源暂时没有可播放的剧集</view><view class="episode-grid"><button v-for="(episode,index) in episodes" :key="episode.key" :id="index===0?'tv-episodes-first':undefined" :data-sn-up="TV_BUILD&&index===0?(detail.routes.length>1?'#tv-route-first':resume?'#tv-resume':'#tv-favorite'):undefined" :data-tv-id="'episode-'+episode.key" :class="['episode',{watched:resume?.episodeKey===episode.key&&resume?.routeId===episode.routeId}]" @click="choose(episode)">{{episode.label}}</button></view><view v-if="detail.synopsis" class="section-heading"><text class="section-title">剧情简介</text><text class="synopsis">{{detail.synopsis}}</text></view><text v-if="detail.cast.length" class="hint">主演：{{detail.cast.join('、')}}</text></template></view></template>
<script setup lang="ts">
import TVNavigation from '@/components/TVNavigation.vue'
import {TV_BUILD} from '@/platform/target'
import {useTVPage} from '@/platform/tv-page'
const tvActive=useTVPage()

import PosterImage from '@/components/PosterImage.vue'
import {AbortController} from '@/platform/cancellation'
import {computed,ref} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import {directRoutes,type DramaDetail,type Episode} from '@/domain/catalog';import type {WatchProgress} from '@/domain/playback';import {resumePosition} from '@/domain/playback';import {loadDetail,adapter} from '@/services/catalog';import {catalogCache,library} from '@/services/library';import {sourceById,sourceState,selectSource,candidates,coolSource,observe} from '@/services/source-store';import {formatTime,notify} from '@/services/device';import {playQueue} from '@/services/play-queue';import {readLocal,writeLocal,removeLocal} from '@/services/storage';import {RecoveryCoordinator} from '@/services/recovery';import {mappings} from '@/services/mappings';import {player} from '@/platform/player';import {playRequest} from '@/services/player-request'
const detail=ref<DramaDetail>(),busy=ref(false),error=ref(''),favorite=ref(false),routeId=ref(''),resume=ref<WatchProgress>(),recovering=ref(false),recoveryContext=ref<{position:number;episodeLabel:string}>();const episodes=computed(()=>detail.value?.routes.find(x=>x.id===routeId.value)?.episodes||[])
let id='',sourceId='',generation=0,controller:AbortController|undefined,disposed=false
onHide(()=>{generation++;controller?.abort();recovery.cancel();recovering.value=false;busy.value=false})
const recovery=new RecoveryCoordinator({adapter,candidates,known:item=>mappings.get(item),cool:coolSource,discard:()=>player.cancelProbe(),probe:(source,work,episode,position,deadline,signal)=>player.probe(playRequest(source,work,episode,position),deadline,'',signal)})
onLoad(query=>{id=String(query?.id||'');sourceId=String(query?.source||sourceState.currentId);detail.value=catalogCache.detail(sourceId,id);if(detail.value)routeId.value=directRoutes(detail.value)[0]?.id||'';recoveryContext.value=readLocal(`freetv:v3:resume:${sourceId}:${id}`);void refresh()});onShow(updateLibrary);onUnload(()=>{disposed=true;generation++;controller?.abort();recovery.cancel()})
function updateLibrary(){resume.value=library.progress().find(x=>x.sourceId===sourceId&&x.vodId===id);favorite.value=!!detail.value&&library.isFavorite(detail.value)}
async function refresh(){const source=sourceById(sourceId);if(!source){error.value='片库配置暂不可用';return}const current=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{const value=await loadDetail(source,id,controller.signal);if(disposed||current!==generation)return;detail.value=value;if(!value.routes.some(x=>x.id===routeId.value))routeId.value=directRoutes(value)[0]?.id||'';updateLibrary()}catch(e){if(!disposed&&current===generation)error.value=(e as Error).message}finally{if(current===generation)busy.value=false}}
function choose(episode:Episode,position?:number){if(!detail.value)return;const source=sourceById(sourceId);if(!source)return;const old=resume.value;const seconds=position??recoveryContext.value?.position??(old?.routeId===episode.routeId&&old.episodeKey===episode.key?resumePosition(old.position,old.duration,old.ended):0);removeLocal(`freetv:v3:resume:${sourceId}:${id}`);playQueue.set({source:{...source},detail:detail.value,episode,position:seconds});uni.navigateTo({url:'/pages/player/player'})}
function continueWatching(){const old=resume.value;if(!old||!detail.value)return;const found=detail.value.routes.find(x=>x.id===old.routeId)?.episodes.find(x=>x.key===old.episodeKey);if(found)choose(found,resumePosition(old.position,old.duration,old.ended));else{notify('上次观看的剧集暂时缺失，正在查找');void reportMissing()}}
function toggleFavorite(){if(detail.value){favorite.value=library.toggleFavorite(detail.value);notify(favorite.value?'已加入追剧':'已移出追剧')}}
async function reportMissing(){if(!detail.value||recovering.value||sourceState.mode==='fixed')return;const original=detail.value,current=++generation;recovering.value=true;const old=resume.value;const episode=old?{key:old.episodeKey,label:old.episodeLabel,routeId:old.routeId,url:'',index:0}:directRoutes(original)[0]?.episodes[0];if(!episode){recovering.value=false;return}observe(`missing:${sourceId}:${id}:${Math.floor(Date.now()/86400000)}`,sourceId,0,'用户反馈缺集');try{const plan=await recovery.prepare(original,episode,old?.position||0,()=>!disposed&&generation===current&&sourceState.mode==='auto',true);if(!plan||disposed||current!==generation){notify('暂未确认更完整的资源，继续保留当前片库');return}mappings.learn(original,plan.match.detail);selectSource(plan.source.id);catalogCache.saveDetail(plan.match.detail);writeLocal(`freetv:v3:resume:${plan.source.id}:${plan.match.detail.id}`,{position:old?.position||0,episodeLabel:old?.episodeLabel||episode.label});uni.redirectTo({url:`/pages/detail/detail?source=${plan.source.id}&id=${encodeURIComponent(plan.match.detail.id)}`})}finally{recovery.cancel();recovering.value=false}}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/index/index'})})}
</script>
<style scoped>.hero,.route-row{gap:0}.hero .poster{margin-right:18px}.route-row .route{margin-right:8px;margin-bottom:8px}</style>
<style scoped>.detail-page{padding-top:calc(10px + var(--status-bar-height,24px))}.hero{align-items:flex-start;gap:18px;margin:18px 0 25px}.poster{width:110px;height:156px;flex-shrink:0;border-radius:10px;background:var(--ft-soft)}.hero-copy{flex:1;min-width:0;padding-top:5px}.hero-copy .title{font-size:23px;margin:9px 0}.favorite{font-size:12px;padding:10px 13px;margin-top:14px}.resume{margin:20px 0}.full{width:100%;margin-top:12px;padding:11px}.episode-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.episode{text-align:left;background:white;border:1px solid var(--ft-border);padding:12px 9px;font-size:12px}.episode.watched{color:var(--ft-accent);border-color:var(--ft-accent)}.route-row{display:flex;gap:8px;margin-bottom:15px;flex-wrap:wrap}.route{padding:7px 10px;font-size:12px;background:var(--ft-soft)}.route.selected{background:var(--ft-accent);color:white}.synopsis{display:block;margin:10px 0 20px;color:var(--ft-muted);font-size:14px;line-height:1.9}.empty{padding:55px 0;text-align:center;color:var(--ft-muted)}</style>
